css:
@keyframes fade-up {
  from {
    opacity: 0;
    transform: translateY(12px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.stack {
  display: grid;
  gap: 12px;
  padding: 24px;
  font-family: system-ui, sans-serif;
}

.notice {
  margin: 0;
  padding: 12px 16px;
  border-radius: 8px;
  background-color: #fed7aa;
  animation: fade-up 500ms ease-out;
}

.later {
  animation: fade-up 500ms ease-out 300ms backwards;
}
